import java.util.*;
import java.math.*;
public class Invoice {public static BigDecimal total(List<Line> lines){return lines.stream().map(l->l.price().multiply(BigDecimal.valueOf(l.quantity())).setScale(2,RoundingMode.HALF_UP)).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2);}}

