import java.util.*;
import java.math.*;
public class InvoiceService {public BigDecimal amount(List<Line> lines){return BigDecimal.valueOf(lines.stream().mapToDouble(l->l.price().doubleValue()*l.quantity()).sum()).setScale(2,RoundingMode.HALF_UP);}}

